# For each 8, check if it's "between" 1s vertically or horizontally

def get_8s_to_fill(rows, cols):
    rowspan_dict = {}
    for r in range(len(rows)):
        all_one_or_empty = all(rows[r][c] in (1, 8) for c in range(len(rows[0])))
        if all_one_or_empty:
            presence = [(c, rows[r][c]) for c in range(len(rows[0])) if rows[r][c] == 1]
            if len(presence) >= 2:
                for i in range(len(presence)-1):
                    start, end = presence[i][0], presence[i+1][0]
                    for c in range(start+1, end):
                        if rows[r][c] == 8:
                            rowspan_dict[(r,c)] = 'h'

    colspan_dict = {}
    for c in range(len(cols)):
        all_one_or_empty = all(rows[r][c] in (1, 8) for r in range(len(rows)))
        if all_one_or_empty:
            presence = [(r, rows[r][c]) for r in range(len(rows)) if rows[r][c] == 1]
            if len(presence) >= 2:
                for i in range(len(presence)-1):
                    start, end = presence[i][0], presence[i+1][0]
                    for r in range(start+1, end):
                        if rows[r][c] == 8:
                            colspan_dict[(r,c)] = 'v'

    return rowspan_dict, colspan_dict

