# Fill 8s that have exactly 2 4-neighbors and those 2 neighbors are collinear (same row or same col)

def fill_gaps_2_neighbor_rule(grid):
    rows = len(grid)
    cols = len(grid[0])
    fill_set = set()

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 8:
                neighbors = []
                for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                    nr, nc = r+dr, c+dc
                    if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == 4:
                        neighbors.append((nr, nc))

                if len(neighbors) == 2:
                    # Check if collinear
                    same_row = neighbors[0][1] == neighbors[1][1]  # same column = vertical alignment
                    same_col = neighbors[0][0] == neighbors[1][0]  # same row = horizontal alignment
                    if same_row or same_col:
                        fill_set.add((r, c))

    return fill_set

