def fill_between_consecutive_pattern(grid, pattern_color=1):
    rows, cols = len(grid), len(grid[0])
    fill_set = set()

    for r in range(rows):
        pattern = [c for c in range(cols) if grid[r][c] == pattern_color]
        for i in range(len(pattern) - 1):
            start, end = pattern[i] + 1, pattern[i+1] - 1
            for c in range(start, end):
                fill_set.add((r, c))

    for c in range(cols):
        pattern = [r for r in range(rows) if grid[r][c] == pattern_color]
        for i in range(len(pattern) - 1):
            start, end = pattern[i] + 1, pattern[i+1] - 1
            for r in range(start, end):
                fill_set.add((r, c))

    return fill_set

